<?php

namespace MongoDB\Driver;

/**
 * <div id="class.mongodb-driver-topologydescription" class="reference"> <h1 class="title">The MongoDB\Driver\TopologyDescription class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.13.0)</p>  <div class="section" id="mongodb-driver-topologydescription.intro">   <h2 class="title">简介</h2>   <p class="simpara">    The <span class="classname"><strong class="classname">MongoDB\Driver\TopologyDescription</strong></span> class is a    value object that represents a topology to which the driver is connected.    Instances of this class are returned by    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-topologychangedevent.php" class="classname">MongoDB\Driver\Monitoring\TopologyChangedEvent</a></span>    methods.   </p>  </div>  <div class="section" id="mongodb-driver-topologydescription.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\TopologyDescription</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-topologydescription.php#mongodb-driver-topologydescription.constants.type-unknown"><var class="varname">TYPE_UNKNOWN</var></a></var><span class="initializer"> = "Unknown"</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="t