ass="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-topologydescription.php#mongodb-driver-topologydescription.constants.type-load-balanced"><var class="varname">TYPE_LOAD_BALANCED</var></a></var><span class="initializer"> = "LoadBalanced"</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-topologydescription.getservers.php" class="methodname" style="color:#CC7832">getServers</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-topologydescription.gettype.php" class="methodname" style="color:#CC7832">getType</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-topologydescription.hasreadableserver.php" class="methodname" style="color:#CC7832">hasReadableServer</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="type MongoDB\Driver\ReadPreference" style="color:#EAB766">MongoDB\Driver\ReadPreference</a></span></span> <span class="parameter" style="color:#3A95FF">\$readPreference</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-topologydescription.haswritableserver.php" class="methodname" style="color:#CC7832">hasWritableServer</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-driver-topologydescription.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-topologydescription.constants.type-unknown"><strong><span>{@link MongoDB\Driver\TopologyDescription::TYPE_UNKNOWN}</span></strong></dt>     <dd>      <span class="simpara">Unknown topology type, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\TopologyDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-topologydescription.constants.type-single"><strong><span>{@link MongoDB\Driver\TopologyDescription::TYPE_SINGLE}</span></strong></dt>     <dd>      <span class="simpara">Single server (i.e. direct connection), returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\TopologyDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-topologydescription.constants.type-sharded"><strong><span>{@link MongoDB\Driver\TopologyDescription::TYPE_SHARDED}</span></strong></dt>     <dd>      <span class="simpara">Sharded cluster, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\TopologyDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-topologydescription.constants.type-replica-set-no-primary"><strong><span>{@link MongoDB\Driver\TopologyDescription::TYPE_REPLICA_SET_NO_PRIMARY}</span></strong></dt>     <dd>      <span class="simpara">Replica set with no primary server, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\TopologyDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-topologydescription.constants.type-replica-set-with-primary"><strong><span>{@link MongoDB\Driver\TopologyDescription::TYPE_REPLICA_SET_WITH_PRIMARY}</span></strong></dt>     <dd>      <span class="simpara">Replica set with a primary server, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\TopologyDescription::getType()}</span>.</span>     </dd>             <dt id="mongodb-driver-topologydescription.constants.type-load-balanced"><strong><span>{@link MongoDB\Driver\TopologyDescription::TYPE_LOAD_BALANCED}</span></strong></dt>     <dd>      <span class="simpara">Load balanced topology, returned by <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\TopologyDescription::getType()}</span>.</span>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\TopologyDescription::getServers} — Returns the servers in the topology</li><li>{@link MongoDB\Driver\TopologyDescription::getType} — Returns a string denoting the type of this topology</li><li>{@link MongoDB\Driver\TopologyDescription::hasReadableServer} — Returns whether the topology has a readable server</li><li>{@link MongoDB\Driver\TopologyDescription::hasWritableServer} — Returns whether the topology has a writable server</li></ul></div>
