class TopologyDescription
{
    public const TYPE_UNKNOWN = 'Unknown';
    public const TYPE_SINGLE = 'Single';
    public const TYPE_SHARDED = 'Sharded';
    public const TYPE_REPLICA_SET_NO_PRIMARY = 'ReplicaSetNoPrimary';
    public const TYPE_REPLICA_SET_WITH_PRIMARY = 'ReplicaSetWithPrimary';
    public const TYPE_LOAD_BALANCED = 'LoadBalanced';


    final private function __construct() {}

    /**
 * <div id="mongodb-driver-topologydescription.getservers" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\TopologyDescription::getServers</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\TopologyDescription::getServers</span> — <span class="dc-title">Returns the servers in the topology</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-topologydescription.getservers-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\TopologyDescription::getServers</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Returns an array of <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php" class="classname">MongoDB\Driver\ServerDescription</a></span>   objects corresponding to the known servers in the topology.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-topologydescription.getservers-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-topologydescription.getservers-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an array of <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-serverdescription.php" class="classname">MongoDB\Driver\ServerDescription</a></span>   objects corresponding to the known servers in the topology.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-topologydescription.getservers-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div></div>
